UML Generator.class_diagram:
classDiagram
    class User {
        +id: UUID
        +name: String
        +email: String
    }
    class Student {
        +takeExam()
        +viewResult()
    }
    class Teacher {
        +createBank()
        +scheduleExam()
        +reviewResults()
    }
    class Admin {
        +manageUsers()
        +configureSettings()
    }
    class Exam {
        +id: UUID
        +startTime: DateTime
        +duration: int
    }
    class QuestionBank {
        +id: UUID
        +addQuestion()
    }
    User <|-- Student
    User <|-- Teacher
    User <|-- Admin
    Teacher --> QuestionBank : manages
    Teacher --> Exam : schedules
    Student --> Exam : takes
    Exam --> QuestionBank : uses

